"""Erratum 1 (2026-10-12): the floor column in scan_result.json / summary.json / README.md is the best of four named rules and omits uniform guessing,
which is itself message-blind and scores 1/k. Corrected floor = max(best of the four order-free rules, 1/k). This script recomputes every headline
number under the corrected floor from the committed scan_result.json, writes summary_v2.json and ERRATA.md, and changes no committed file otherwise.
Prompted by Vina's question on Colony post 3fa0c488 (comment 64ab035f): the per-bank distribution showed a floor below chance, which cannot be."""
import json, statistics, collections
S = json.load(open("scan_result.json")); B = {k: v for k, v in S["banks"].items() if v.get("state") == "scored"}
old = json.load(open("summary.json"))
for v in B.values(): v["floor2"] = max(v["best"], v["uniform"]); v["floor_below_uniform"] = v["best"] < v["uniform"]
rows = [x for x in S["measurements"] if "best" in x]; live = [x for x in rows if not x["retracted"]]
for x in rows: x["floor2"] = B[x["bank_id"]]["floor2"]
def q(a, p): a = sorted(a); return a[int(round(p * (len(a) - 1)))]
gap2 = [x["floor2"] - x["chance"] for x in live]; floors2 = [v["floor2"] for v in B.values()]; floors1 = [v["best"] for v in B.values()]
new = {
 "definition": "floor = max(best of {constant answer, longest option, shortest option, constant first word}, 1/k) where k is the modal option count of the bank",
 "rows_served": old["rows_served"], "rows_scored": len(rows), "rows_live": len(live), "banks_scored": len(B),
 "banks_floor_below_uniform_before_erratum": sum(1 for v in B.values() if v["floor_below_uniform"]),
 "banks_floor_below_uniform_list": sorted([(k[:12], v["n"], v["k"], v["best"], v["uniform"], v["best_rule"]) for k, v in B.items() if v["floor_below_uniform"]]),
 "live_rows_on_those_banks": sum(1 for x in live if B[x["bank_id"]]["floor_below_uniform"]),
 "live_chance_uniform": sum(x["chance_is_uniform"] for x in live),
 "live_gap_ge_5pp": sum(1 for g in gap2 if g >= 0.05), "live_gap_ge_10pp": sum(1 for g in gap2 if g >= 0.10), "live_gap_ge_25pp": sum(1 for g in gap2 if g >= 0.25),
 "live_gap_median_pp": round(100 * statistics.median(gap2), 1), "live_gap_min_pp": round(100 * min(gap2), 1), "live_gap_max_pp": round(100 * max(gap2), 1),
 "live_gap_quartiles_pp": [round(100 * q(gap2, p), 1) for p in (0, .25, .5, .75, 1)],
 "floor_quartiles": [q(floors2, p) for p in (0, .25, .5, .75, 1)], "floor_quartiles_before_erratum": [q(floors1, p) for p in (0, .25, .5, .75, 1)],
 "live_rows_floor_equals_chance": sum(1 for g in gap2 if abs(g) < 0.005),
 "live_english_below_floor": sum(1 for x in live if x["english"] < x["floor2"]), "live_marked_below_floor": sum(1 for x in live if x["ainglish"] < x["floor2"]),
 "live_both_below_floor": sum(1 for x in live if x["english"] < x["floor2"] and x["ainglish"] < x["floor2"]),
 "live_both_below_by_state": dict(collections.Counter(str(x["settlement_state"]) + ("/replication" if x["is_replication"] else "/original") for x in live if x["english"] < x["floor2"] and x["ainglish"] < x["floor2"])),
 "banks_orderfree_perfect": sum(1 for v in B.values() if v["floor2"] == 1.0), "live_rows_on_perfect_banks": sum(1 for x in live if x["floor2"] == 1.0),
 "banks_recurring_option_never_key": old["banks_recurring_option_never_key"],
}
json.dump(new, open("summary_v2.json", "w"), indent=1, sort_keys=True)
cmp = [("live_gap_ge_5pp", old["live_gap_ge_5pp"], new["live_gap_ge_5pp"]), ("live_gap_ge_25pp", old["live_gap_ge_25pp"], new["live_gap_ge_25pp"]), ("live_gap_median_pp", old["live_gap_median_pp"], new["live_gap_median_pp"]),
       ("banks_orderfree_perfect", old["banks_orderfree_perfect"], new["banks_orderfree_perfect"]), ("live_rows_on_perfect_banks", old["live_rows_on_perfect_banks"], new["live_rows_on_perfect_banks"]),
       ("live_english_below_floor", old["live_english_below_best"], new["live_english_below_floor"]), ("live_marked_below_floor", old["live_marked_below_best"], new["live_marked_below_floor"]), ("live_both_below_floor", old["live_both_below_best"], new["live_both_below_floor"])]
L = ["# ERRATA", "", "## Erratum 1 (2026-10-12): the floor omitted uniform guessing", "",
     "Prompted by Vina's question on the Colony post (3fa0c488, comment 64ab035f). The `best` column in `scan_result.json`, the `floor` in `README.md` and every number in `summary.json` take the floor to be the best of the four named order-free rules. Uniform guessing over the options is also message-blind and scores 1/k, so on a bank where none of the four rules reaches 1/k the stated floor is below what a non-reader scores. Corrected definition, used in `summary_v2.json` (generated by `erratum_floor.py` from the committed `scan_result.json`): " + new["definition"] + ".", "",
     f"Banks affected: {new['banks_floor_below_uniform_before_erratum']} of {new['banks_scored']} scored banks, carrying {new['live_rows_on_those_banks']} live rows (bank, n, k, best of four, 1/k, best rule):", ""]
L += [f"- `{b}` n {n} k {k} best {best} uniform {u} ({r})" for b, n, k, best, u, r in new["banks_floor_below_uniform_list"]]
L += ["", "Headline numbers before and after the correction (rows not retracted):", "", "| number | summary.json | summary_v2.json |", "|---|---|---|"] + [f"| {k} | {a} | {b} |" for k, a, b in cmp]
L += ["", f"Floor quartiles over scored banks: before {new['floor_quartiles_before_erratum']}, after {new['floor_quartiles']}. Gap (floor minus declared chance) quartiles in points, after: {new['live_gap_quartiles_pp']}; live rows where the corrected floor equals the declared chance: {new['live_rows_floor_equals_chance']}.", "",
      "The original files are left as committed; the Colony post's numbers were computed from `summary.json` and are listed above beside their corrected values. Nothing here is a measurement.", ""]
open("ERRATA.md", "w").write("\n".join(L)); print(json.dumps({k: v for k, v in new.items() if k != "banks_floor_below_uniform_list"}, indent=0)); print("affected:", new["banks_floor_below_uniform_list"][:12])
